package kinuvo.harness.core

import dev.ynagai.a2ui.core.protocol.A2uiJson
import dev.ynagai.a2ui.core.protocol.CatalogDefinition
import kinuvo.harness.core.tools.ShowUiTool
import kinuvo.protocol.ProtocolJson
import kinuvo.protocol.UiCatalog
import kotlinx.coroutines.test.runTest
import kotlinx.serialization.json.*
import kotlin.test.*
import kinuvo.app.surface.surfaceCatalog

class ShowUiToolTest {
    private val catalog = ProtocolJson.decodeFromString(UiCatalog.serializer(), """
        {"catalogId":"kinuvo:test","protocolVersion":"1.0","components":{"Text":{
          "type":"object","properties":{"component":{"const":"Text"},"text":{"type":"string"}},
          "required":["component","text"]}},"${'$'}defs":{"anyComponent":{"oneOf":[{"${'$'}ref":"#/components/Text"}]}}}
    """)
    private val tool = ShowUiTool(listOf(catalog))
    private fun args(message: String) = ProtocolJson.parseToJsonElement("""{"messages":[$message]}""").jsonObject
    private fun create(component: String = "Text", id: String = "root") = """
        {"createSurface":{"surfaceId":"form","catalogId":"kinuvo:test",
          "components":[{"id":"$id","component":"$component","text":"Hello"}]}}
    """

    @Test fun editableWidgets() = runTest {
        val basic = A2uiJson.lenient.decodeFromString(CatalogDefinition.serializer(), checkNotNull(javaClass.getResource("/a2ui-basic.json")).readText())
        val definition = surfaceCatalog(basic)
        val catalog = ProtocolJson.decodeFromJsonElement(UiCatalog.serializer(), A2uiJson.strict.encodeToJsonElement(CatalogDefinition.serializer(), definition))
        val tool = ShowUiTool(listOf(catalog))
        for (name in listOf("editable-tasks", "weekly-timesheet")) {
            val raw = checkNotNull(javaClass.getResource("/$name.json")).readText()
            assertEquals("Shown to the user.", tool.execute(args(raw)))
        }
    }

    @Test fun kinuvoCatalogComponents() = runTest {
        val basic = A2uiJson.lenient.decodeFromJsonElement(CatalogDefinition.serializer(), ProtocolJson.encodeToJsonElement(UiCatalog.serializer(), basicCatalog))
        val definition = surfaceCatalog(basic)
        val catalog = ProtocolJson.decodeFromJsonElement(UiCatalog.serializer(), A2uiJson.strict.encodeToJsonElement(CatalogDefinition.serializer(), definition))
        val tool = ShowUiTool(listOf(basicCatalog, catalog))
        val components = """[
            {"id":"root","component":"Column","children":["badge","space","item","table","transition"]},
            {"id":"badge","component":"Badge","label":"Ready"},
            {"id":"space","component":"Spacer","minSize":12},
            {"id":"item","component":"ListItem","title":"Item","leading":"badge","trailing":"button"},
            {"id":"transition","component":"Transition","child":"badge"},
            {"id":"table","component":"Table","children":{"componentId":"row","path":"/rows"}},
            {"id":"row","component":"TableRow","children":["cell"]},
            {"id":"cell","component":"TableCell","children":["button"]},
            {"id":"button","component":"Button","child":"label","action":{"event":{"name":"choose"}}},
            {"id":"label","component":"Text","text":"Choose"}]
        """
        val message = """{"createSurface":{"surfaceId":"table","catalogId":"${catalog.catalogId}","components":$components,"dataModel":{"rows":[{},{}]}}}"""
        assertEquals("Shown to the user.", tool.execute(args(message)))
        for ((name, required) in mapOf("Badge" to "label", "ListItem" to "title", "Table" to "children", "TableRow" to "children", "TableCell" to "children", "Transition" to "child")) {
            val invalid = """{"createSurface":{"surfaceId":"bad","catalogId":"${catalog.catalogId}","components":[{"id":"root","component":"$name"}]}}"""
            val error = assertFailsWith<IllegalArgumentException> { tool.execute(args(invalid)) }.message.orEmpty()
            assertTrue("Component 'root' ($name)" in error, error)
            assertTrue(required in error, error)
        }
    }

    @Test fun validSurface() = runTest {
        assertEquals("Shown to the user.", tool.execute(args(create())))
    }

    @Test fun invalidSurfaces() = runTest {
        assertFails { tool.execute(args(create(component = "Unknown"))) }
        assertFails { tool.execute(args(create(id = "other"))) }
        assertFails { tool.execute(args("""{"updateComponents":{"surfaceId":"form","components":[]}}""")) }
        assertFails { tool.execute(args("42")) }
    }

    @Test fun catalogRoundTripPreservesDefinitions() {
        val definition = A2uiJson.strict.decodeFromJsonElement(CatalogDefinition.serializer(),
            ProtocolJson.encodeToJsonElement(UiCatalog.serializer(), catalog))
        val roundTrip = ProtocolJson.decodeFromJsonElement(UiCatalog.serializer(),
            A2uiJson.strict.encodeToJsonElement(CatalogDefinition.serializer(), definition))
        assertEquals(catalog, roundTrip)
        assertEquals(catalog.defs, definition.schemaKeywords["${'$'}defs"])
    }

