        assertFalse("Component 'title'" in error, error)
    }

    @Test fun sessionAttempt5() = runTest {
        val payload = ProtocolJson.parseToJsonElement("""{"messages":[{"version":"v1.0","createSurface":{"surfaceId":"trip-planner","catalogId":"https://a2ui.org/specification/v1_0/catalogs/basic/catalog.json","root":"root","components":[{"id":"root","component":"Column","children":["destination"]},{"id":"destination","component":"TextField","label":"Destination"}],"dataModel":{}}}]}""").jsonObject
        val error = assertFailsWith<IllegalArgumentException> { basicTool.execute(payload) }.message.orEmpty()
        println("SESSION_ATTEMPT_5=$error")
        assertEquals("Message 0: createSurface has unknown key 'root'", error)
        assertFalse("ignoreUnknownKeys" in error)
    }

    @Test fun missingCatalogId() = runTest {
        val payload = ProtocolJson.parseToJsonElement("""{"messages":[{"createSurface":{"surfaceId":"trip-planner","components":[{"id":"root","component":"Text","text":"Hi"}]}}]}""").jsonObject
        val error = assertFailsWith<IllegalArgumentException> { basicTool.execute(payload) }.message.orEmpty()
        assertTrue(error.startsWith("Message 0: createSurface needs a catalogId"), error)
    }

