        val payload = ProtocolJson.parseToJsonElement("""{"messages":[{"version":"v1.0","createSurface":{"surfaceId":"trip-planner","catalogId":"https://a2ui.org/specification/v1_0/catalogs/basic/catalog.json","components":[{"id":"root","component":"Card","child":"form"},{"id":"form","component":"Column","children":["title","destination","dates","travellers","flexible","style","submit"]},{"id":"title","component":"Text","text":"Plan a short trip"},{"id":"destination","component":"TextField","label":"Destination","value":{"path":"/trip/destination"},"placeholder":"Where would you like to go?"},{"id":"dates","component":"Row","children":["startDate","endDate"]},{"id":"startDate","component":"DateTimeInput","label":"Start date","value":{"path":"/trip/startDate"},"enableDate":true},{"id":"endDate","component":"DateTimeInput","label":"End date","value":{"path":"/trip/endDate"},"enableDate":true},{"id":"travellers","component":"Slider","label":"Number of travellers","min":1,"max":8,"steps":7,"value":{"path":"/trip/travellers"}},{"id":"flexible","component":"CheckBox","label":"Flexible dates","value":{"path":"/trip/flexibleDates"}},{"id":"style","component":"ChoicePicker","label":"Travel style","variant":"mutuallyExclusive","displayStyle":"chips","options":[{"label":"Relaxed","value":"relaxed"},{"label":"Adventure","value":"adventure"},{"label":"Culture","value":"culture"}],"value":{"path":"/trip/travelStyle"}},{"id":"submit","component":"Button","variant":"primary","child":"submitLabel","action":{"event":{"name":"submitTripPlan","context":{"destination":{"path":"/trip/destination"},"startDate":{"path":"/trip/startDate"},"endDate":{"path":"/trip/endDate"},"travellers":{"path":"/trip/travellers"},"flexibleDates":{"path":"/trip/flexibleDates"},"travelStyle":{"path":"/trip/travelStyle"}}}}},{"id":"submitLabel","component":"Text","text":"Submit"}],"dataModel":{"trip":{"destination":"","startDate":"","endDate":"","travellers":2,"flexibleDates":false,"travelStyle":["relaxed"]}}}